package com.holdmyspot.codexunleashed.scheduler;
import java.io.*;
import java.lang.foreign.*;
import java.lang.invoke.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.TimeoutException;
import java.util.regex.Pattern;
/**
 * Exercises the actual Java owner through native Windows launches and handle accounting.
 */
public final class OwnerChecks
{
    private static Path root;
    private static Path java;
    private static Path python;
    private static String classes;
    private static String nativeInvalidError;
    /**
     * Runs the focused real lifecycle and failure suite.
     * @param arguments owned fixture directory, optional root-only-regression mode
     * @throws Exception if an observable gate fails
     */
    public static void main(String[] arguments) throws Exception
    {
        root=Path.of(arguments[0]);
        python=Path.of(arguments[1]);
