         * @param name native symbol
         * @param result native result layout
         * @param layouts argument layouts
         * @return the bound operation
         */
        private MethodHandle bind(String name,MemoryLayout result,MemoryLayout...layouts)
        {
            return Linker.nativeLinker().downcallHandle(library.find(name).orElseThrow(),FunctionDescriptor.of(result,layouts));
        }
        /**
         * Creates fixture output with sharing so assertions can inspect it while still borrowed.
         * @param path output file
         * @return owned native file handle
         * @throws Exception if acquisition fails
         */
        MemorySegment open(Path path) throws Exception
        {
            var bytes=(path.toString()+'\0').getBytes(StandardCharsets.UTF_16LE);
            var text=arena.allocate(bytes.length,2);text.copyFrom(MemorySegment.ofArray(bytes));
