                check(handle.address()!=-1 && handle.address()!=0,"fixture output acquisition failed");return handle;
            }
            catch(Throwable e){throw failure(e);}
        }
        /**
         * Appends a borrowed-handle liveness marker through actual native output.
         * @param handle caller-owned native file
         * @param text text to write
         * @throws Exception if the owner closed the borrowed handle
         */
        void write(MemorySegment handle,String text) throws Exception
        {
            byte[] bytes=text.getBytes(StandardCharsets.UTF_8);var data=arena.allocate(bytes.length);data.copyFrom(MemorySegment.ofArray(bytes));
            var written=arena.allocate(ValueLayout.JAVA_INT);
            try
            {
                int status=(int)bind("WriteFile",ValueLayout.JAVA_INT,ValueLayout.ADDRESS,ValueLayout.ADDRESS,ValueLayout.JAVA_INT,ValueLayout.ADDRESS,ValueLayout.ADDRESS)
                    .invoke(handle,data,bytes.length,written,MemorySegment.NULL);
                check(status!=0 && written.get(ValueLayout.JAVA_INT,0)==bytes.length,"borrowed output closed or truncated");
            }
            catch(Throwable e){throw failure(e);}
        }
        /**
         * Counts handles owned by the current native JVM process.
         * @return the native unsigned handle count
         * @throws Exception if acquisition fails
         */
        long handles() throws Exception
        {
            var count=arena.allocate(ValueLayout.JAVA_INT);
            try
            {
                var current=(MemorySegment)bind("GetCurrentProcess",ValueLayout.ADDRESS).invoke();
                int status=(int)bind("GetProcessHandleCount",ValueLayout.JAVA_INT,ValueLayout.ADDRESS,ValueLayout.ADDRESS).invoke(current,count);
                check(status!=0,"native handle accounting failed");return Integer.toUnsignedLong(count.get(ValueLayout.JAVA_INT,0));
            }
            catch(Throwable e){throw failure(e);}
        }
        /**
         * Closes the fixture-owned file.
         * @param handle native file handle
         * @throws Exception if native close fails
         */
        void closeHandle(MemorySegment handle) throws Exception
        {
            try {check((int)bind("CloseHandle",ValueLayout.JAVA_INT,ValueLayout.ADDRESS).invoke(handle)!=0,"fixture close failed");}
            catch(Throwable e){throw failure(e);}
        }
        /**
         * Preserves unchecked failures and translates checked invocation throwables.
         * @param failure native invocation failure
         * @return checked exception for the fixture boundary
         */
        private Exception failure(Throwable failure)
        {
            if(failure instanceof Error error)throw error;
            if(failure instanceof Exception exception)return exception;
            return new Exception(failure);
        }
        @Override
        public void close(){arena.close();}
    }
}

