package com.holdmyspot.codexunleashed.scheduler;
import java.nio.file.*;
import java.util.*;
/**
 * Supplies short, independently expiring real process-tree fixtures.
 */
public final class Workload
{
    /**
     * Emits launch inputs, creates a surviving child, or waits until its independent expiry.
     * @param arguments fixture mode, state path and literal arguments
     * @throws Exception if fixture I/O or launch fails
     */
    public static void main(String[] arguments) throws Exception
    {
        switch (arguments[0])
        {
            case "inspect" ->
            {
                System.out.println("DIRECT_ARGS="+Base64.getEncoder().encodeToString(String.join("\n",Arrays.copyOfRange(arguments,2,arguments.length)).getBytes(java.nio.charset.StandardCharsets.UTF_8)));
                System.out.println("ENV="+System.getenv("OWNER_LITERAL"));
                System.out.println("CWD="+Path.of("").toAbsolutePath());
                System.err.println("STDERR_RETAINED");
                System.exit(7);
            }
            case "tree" ->
            {
                Path state=Path.of(arguments[1]);
                new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin","java.exe").toString(),
                    "-cp",System.getProperty("java.class.path"),Workload.class.getName(),"child",state.toString())
                    .inheritIO().start();
                long deadline=System.nanoTime()+java.time.Duration.ofSeconds(15).toNanos();
                while (Files.exists(state)==false)
                {
                    if (System.nanoTime()>=deadline)throw new AssertionError("Child readiness deadline expired");
                    Thread.sleep(10);
                }
                System.exit(0);
            }
            case "child" ->
            {
                Path state=Path.of(arguments[1]);
                Path pending=state.resolveSibling(state.getFileName().toString()+".pending");
                Files.writeString(pending,Long.toString(ProcessHandle.current().pid()));
                Files.move(pending,state,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);
                System.out.println("SURVIVING_CHILD_READY");
                Thread.sleep(60000);
            }
            case "hold" -> Thread.sleep(60000);
            default -> throw new IllegalArgumentException("Unknown fixture mode");
        }
    }
}

